package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;import com.lianxibu.site.domain.jobs.SourceContractFacts;import com.lianxibu.site.service.jobs.OperationalRuleEngine.*;import java.time.*;import org.junit.jupiter.api.Test;
class SourceContractWatermarkTest {
 static final Instant START=OperationalRuleEngineTest.START;static final OperationalRuleEngine ENGINE=new OperationalRuleEngine();static final Key KEY=new Key("OPS-07","collector","fictional-source");
 static SourceContracts reading(int minute,long config,String epoch,long total,long window,Instant reviewed){Instant at=START.plusSeconds(minute*60L);return new SourceContracts(new SourceContractFacts.Evidence(KEY.resourceKey(),config,epoch,total,window,1,at,at,at,reviewed));}
 static State tick(State state,int minute,SourceContracts reading){return ENGINE.sample(state,OperationalRuleEngineTest.config(7),1,START.plusSeconds(minute*60L),true,reading).state();}
 @Test void knownNativeZeroInitialAndOneErrorWarningThreeCritical(){State state=tick(State.empty(KEY),0,reading(0,1,"a".repeat(64),0,0,START));assertEquals(Status.NORMAL,state.status());state=tick(state,1,reading(1,1,"a".repeat(64),1,1,START));assertEquals(Level.WARNING,state.level());assertTrue(state.guards().contains(Guard.RETRY_MEMBER));state=tick(state,2,reading(2,1,"a".repeat(64),3,3,START));assertEquals(Level.CRITICAL,state.level());assertTrue(state.guards().contains(Guard.NEW_FETCH));assertEquals(3,state.counters().get("source_total"));assertEquals(1,state.counters().get("source_failed_config"));}
 @Test void permanentEpochAndTotalWatermarksSurviveCodecReloadAndUnknown(){State state=tick(State.empty(KEY),0,reading(0,1,"b".repeat(64),1,1,START));state=OperationalStateCodec.decode(OperationalStateCodec.encode(state));state=ENGINE.sample(state,OperationalRuleEngineTest.config(7),1,START.plusSeconds(60),false,null).state();assertEquals(1,state.counters().get("source_total"));assertEquals(1,state.counters().get("source_failed_config"));State next=tick(state,2,reading(2,1,"b".repeat(64),1,0,START));assertEquals(1,next.counters().get("source_total"));assertTrue(next.guards().contains(Guard.RETRY_MEMBER));assertFalse(next.recoveryReady());assertEquals(next,OperationalStateCodec.decode(OperationalStateCodec.encode(next)));}
 @Test void noFalseHealthyOnCounterRollbackRepeatedAcquisitionWrongSourceOrOldApproval(){State state=tick(State.empty(KEY),0,reading(0,1,"a".repeat(64),2,2,START));State rollback=tick(state,1,reading(1,1,"a".repeat(64),1,1,START));assertEquals(Status.TELEMETRY_UNKNOWN,rollback.status());assertEquals(2,rollback.counters().get("source_total"));State repeated=ENGINE.sample(state,OperationalRuleEngineTest.config(7),1,START.plusSeconds(60),true,reading(0,1,"a".repeat(64),2,2,START)).state();assertEquals(Status.TELEMETRY_UNKNOWN,repeated.status());State changed=tick(state,1,reading(1,2,"c".repeat(64),0,0,START));for(int m=2;m<35;m++)changed=tick(changed,m,reading(m,2,"c".repeat(64),0,0,START));assertFalse(changed.recoveryReady());assertTrue(changed.guards().contains(Guard.RETRY_MEMBER));}
 @Test void sameConfigNewEpochAndZeroCannotDeclareOwnerRevalidation(){State state=tick(State.empty(KEY),0,reading(0,1,"a".repeat(64),3,3,START));for(int m=1;m<=32;m++)state=tick(state,m,reading(m,1,"b".repeat(64),0,0,START));assertFalse(state.recoveryReady());assertTrue(state.guards().contains(Guard.NEW_FETCH));assertEquals(1,state.counters().get("source_failed_config"));}
 @Test void laterOriginalManualReviewNewConfigAndThirtyContinuousMinutesAreRequired(){State state=tick(State.empty(KEY),0,reading(0,1,"a".repeat(64),3,3,START));Instant reviewed=START.plusSeconds(1);for(int m=1;m<=30;m++){state=tick(state,m,reading(m,2,"b".repeat(64),0,0,reviewed));assertFalse(state.recoveryReady());}state=tick(state,31,reading(31,2,"b".repeat(64),0,0,reviewed));assertEquals(Status.RESOLVED,state.status());assertFalse(state.recoveryReady());assertTrue(state.guards().isEmpty());state=ENGINE.sample(state,OperationalRuleEngineTest.config(7),1,START.plusSeconds(32*60),false,null).state();assertFalse(state.recoveryReady());assertEquals(1,state.counters().get("source_failed_config"));assertEquals(2,state.counters().get("source_config"));}
 @Test void syntheticSimpleReadingCannotReplaceRequiredNativeEvidence(){State state=tick(State.empty(KEY),0,reading(0,1,"a".repeat(64),3,3,START));State unavailable=ENGINE.sample(state,OperationalRuleEngineTest.config(7),1,START.plusSeconds(60),true,new ContractFailures(0,0,true)).state();assertEquals(Status.TELEMETRY_UNKNOWN,unavailable.status());assertEquals(3,unavailable.counters().get("source_total"));State missing=tick(state,1,new SourceContracts(null));assertEquals(Status.TELEMETRY_UNKNOWN,missing.status());}
 @Test void lateHistoryWithoutBaselineAndFutureOrStaleObservationsStayUnknown(){State noBaseline=tick(State.empty(KEY),0,reading(0,1,"a".repeat(64),3,0,START));assertEquals(Status.TELEMETRY_UNKNOWN,noBaseline.status());Instant old=START.minusSeconds(121);var e=new SourceContractFacts.Evidence(KEY.resourceKey(),1,"a".repeat(64),0,0,1,old,START,START,START);assertEquals(Status.TELEMETRY_UNKNOWN,tick(State.empty(KEY),0,new SourceContracts(e)).status());var other=new SourceContractFacts.Evidence("fictional-other",1,"a".repeat(64),0,0,1,START,START,START,START);assertEquals(Status.TELEMETRY_UNKNOWN,tick(State.empty(KEY),0,new SourceContracts(other)).status());}
}
